use vstd::prelude::*;

#[derive(Clone)]
struct Complex {
    real: i32,
    imag: i32,
}

verus! {
    spec fn is_close_to_zero(imag: i32, tol: i32) -> bool {
        (imag.abs() <= tol * 2)
    }

    fn real_if_close(arr: Vec<Complex>, tol: i32) -> (result: Vec<Complex>)
        requires
            arr.len() > 0,
            tol > 0,
        ensures
            result.len() == arr.len(),
            forall |i: usize| 0 <= i < arr.len() ==> result[i].real == arr[i].real,
            (forall |i: usize| 0 <= i < arr.len() ==> is_close_to_zero(arr[i].imag, tol)) ==> 
                (forall |i: usize| 0 <= i < arr.len() ==> result[i].imag == 0),
            (forall |i: usize| 0 <= i < arr.len() ==> arr[i].imag == 0) ==> 
                (forall |i: usize| 0 <= i < arr.len() ==> result[i] == arr[i]),
    {
        let mut all_close = true;
        let mut result: Vec<Complex> = Vec::new();

        for i in 0..arr.len()
            invariant
                0 <= i <= arr.len(),
                all_close ==> (forall |j: usize| 0 <= j < i ==> is_close_to_zero(arr[j].imag, tol)),
                result.len() == i,
        {
            if !is_close_to_zero(arr[i].imag, tol) {
                all_close = false;
            }
            result.push(Complex {
                real: arr[i].real,
                imag: if all_close { 0 } else { arr[i].imag },
            });
        }

        result
    }
}
